                    <p class="text-muted small">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public string Device { get; set; } = "";
    [Parameter] public string Location { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         role="button" @onclick="ToggleExpanded" style="cursor: pointer;">
        <span>🔑 Change Password</span>
        <span>@(isExpanded ? "▲" : "▼")</span>
    </div>
    @if (isExpanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(message))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                    @message
                    <button type="button" class="btn-close" @onclick="() => message = null"></button>
                </div>
            }
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword" />
            </div>
            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@isUpdating">
                @if (isUpdating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? message;
    private bool isError;
    private bool isUpdating;

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            message = "All password fields are required.";
            isError = true;
            return;
        }
        if (newPassword != confirmPassword)
        {
            message = "New password and confirmation do not match.";
            isError = true;
            return;
        }
        if (newPassword.Length < 8)
        {
            message = "New password must be at least 8 characters.";
            isError = true;
            return;
        }

        isUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            message = "Password updated successfully.";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch
        {
            message = "Failed to update password. Please try again.";
            isError = true;
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<div class="card">
    <div class="card-header">Active Sessions</div>
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => RequestRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

<RevokeSessionDialog Visible="sessionToRevoke is not null"
                     Device="@(sessionToRevoke?.Device ?? "")"
                     Location="@(sessionToRevoke?.Location ?? "")"
                     OnConfirm="ConfirmRevoke"
                     OnCancel="CancelRevoke" />

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? sessionToRevoke;

    private void RequestRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<div class="card">
    <div class="card-header">Live Preview</div>
    <div class="card-body" style="@PreviewStyle">
        <h5 style="@FontStyle">Settings Dashboard</h5>
        <p style="@FontStyle">This is a preview of how your content will look with the selected settings.</p>
        <div class="d-flex gap-2 mb-2">
            <button class="btn btn-primary btn-sm">Primary</button>
            <button class="btn btn-secondary btn-sm">Secondary</button>
            <button class="btn btn-outline-primary btn-sm">Outline</button>
        </div>
        <div class="form-check">
            <input class="form-check-input" type="checkbox" checked disabled>
            <label class="form-check-label" style="@FontStyle">Sample checkbox</label>
        </div>
        @if (Settings.CompactMode)
        {
            <span class="badge bg-info mt-2">Compact mode active — reduced spacing</span>
        }
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings Settings { get; set; } = new("Light", "Medium", "English", false);

    private string PreviewStyle
    {
        get
        {
            var bg = Settings.Theme switch
            {
                "Dark" => "background-color: #1a1a2e; color: #e0e0e0;",
                "System" => "background-color: #f0f0f0; color: #333;",
                _ => "background-color: #ffffff; color: #212529;"
            };
            var padding = Settings.CompactMode ? "padding: 0.5rem;" : "padding: 1rem;";
            return $"{bg} {padding} border-radius: 0.375rem; min-height: 150px;";
        }
    }

    private string FontStyle => Settings.FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };
}

