@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<div class="card">
    <div class="card-header">Live Preview</div>
    <div class="card-body" style="@PreviewStyle">
        <h5 style="@FontStyle">Settings Dashboard</h5>
        <p style="@FontStyle">This is a preview of how your content will look with the selected settings.</p>
        <div class="d-flex gap-2 mb-2">
            <button class="btn btn-primary btn-sm">Primary</button>
            <button class="btn btn-secondary btn-sm">Secondary</button>
            <button class="btn btn-outline-primary btn-sm">Outline</button>
        </div>
        <div class="form-check">
            <input class="form-check-input" type="checkbox" checked disabled>
            <label class="form-check-label" style="@FontStyle">Sample checkbox</label>
        </div>
        @if (Settings.CompactMode)
        {
            <span class="badge bg-info mt-2">Compact mode active — reduced spacing</span>
        }
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings Settings { get; set; } = new("Light", "Medium", "English", false);

    private string PreviewStyle
    {
        get
        {
            var bg = Settings.Theme switch
            {
                "Dark" => "background-color: #1a1a2e; color: #e0e0e0;",
                "System" => "background-color: #f0f0f0; color: #333;",
                _ => "background-color: #ffffff; color: #212529;"
            };
            var padding = Settings.CompactMode ? "padding: 0.5rem;" : "padding: 1rem;";
            return $"{bg} {padding} border-radius: 0.375rem; min-height: 150px;";
        }
    }

    private string FontStyle => Settings.FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };
}

arguments.file_text:
@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<h4 class="mb-4">Profile Settings</h4>

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-8">
        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="displayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="bio"></textarea>
        </div>
    </div>
    <div class="col-md-4 text-center">
        <div class="mb-3">
            <img src="@avatarUrl" alt="Avatar" class="rounded-circle mb-2"
                 style="width: 120px; height: 120px; object-fit: cover; border: 3px solid #dee2e6;" />
            <div class="text-muted small text-break">@avatarUrl</div>
        </div>
    </div>
</div>

<div class="d-flex gap-2">
    <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
        @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save Changes
    </button>
    <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string avatarUrl = "";
    private string? statusMessage;
    private bool isError;
    private bool isSaving;

    // Snapshot of last-saved state for discard
    private UserProfile? savedSnapshot;

    protected override void OnParametersSet()
    {
        if (Profile is not null && savedSnapshot is null)
        {
            ApplyProfile(Profile);
            savedSnapshot = Profile;
        }
    }

    private void ApplyProfile(UserProfile p)
    {
        displayName = p.DisplayName;
        email = p.Email;
        bio = p.Bio;
        avatarUrl = p.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        try
        {
            var updated = new UserProfile(displayName, email, avatarUrl, bio);
            await OnSave.InvokeAsync(updated);
            savedSnapshot = updated;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save profile.";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (savedSnapshot is not null)
        {
            ApplyProfile(savedSnapshot);
            statusMessage = null;
        }
    }
}

@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<h4 class="mb-4">Notification Preferences</h4>

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

<div class="card mb-3">
    <div class="card-body">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
            <label class="form-check-label" for="emailNotif">
                <strong>Email Notifications</strong>
                <div class="text-muted small">Receive notifications via email</div>
            </label>
        </div>
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
            <label class="form-check-label" for="pushNotif">
                <strong>Push Notifications</strong>
                <div class="text-muted small">Receive browser push notifications</div>
            </label>
        </div>
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">
                <strong>Weekly Digest</strong>
                <div class="text-muted small">Get a weekly summary of activity</div>
            </label>
        </div>
    </div>
</div>

<div class="card mb-3">
    <div class="card-header">Channel Muting</div>
    <div class="card-body">
        @foreach (var channel in allChannels)
        {
            var isMuted = mutedChannels.Contains(channel);
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                       checked="@isMuted"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <label class="form-check-label" for="@($"ch-{channel}")">
                    @channel @if (isMuted) { <span class="badge bg-secondary ms-1">Muted</span> }
                </label>
            </div>
        }
    </div>
</div>

<button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
    @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
    Save Preferences
</button>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private string? statusMessage;
    private bool isSaving;

    private static readonly string[] allChannels = { "general", "announcements", "marketing", "engineering", "support" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !initialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            initialized = true;
        }
    }

    private bool initialized;

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        try
        {
            var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
            await OnSave.InvokeAsync(updated);
            statusMessage = "Notification preferences saved!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<h4 class="mb-4">Security Settings</h4>

<ChangePasswordPanel OnChangePassword="HandleChangePassword" />

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small">Add an extra layer of security to your account</div>
            </div>
            <div class="d-flex align-items-center gap-2">
                @if (twoFactorEnabled)
                {
                    <span class="badge bg-success">Enabled</span>
                }
                else
                {
                    <span class="badge bg-warning text-dark">Disabled</span>
                }
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" @bind="twoFactorEnabled" />
                </div>
            </div>
        </div>
    </div>
</div>

@if (Security?.LastPasswordChange is not null)
{
    <div class="text-muted small mb-3">
        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
    </div>
}

<ActiveSessionsTable Sessions="sessions" OnRevoke="HandleRevoke" />

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool twoFactorEnabled;
    private List<ActiveSession> sessions = new();
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (Security is not null && !initialized)
        {
            twoFactorEnabled = Security.TwoFactorEnabled;
            sessions = Security.Sessions.ToList();
            initialized = true;
        }
    }

    private async Task HandleChangePassword((string Current, string New) passwords) =>
        await OnChangePassword.InvokeAsync(passwords);

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
        sessions = sessions.Where(s => s.Id != sessionId).ToList();
    }
}

@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<h4 class="mb-4">Appearance Settings</h4>

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-6">
        <div class="card mb-3">
            <div class="card-header">Theme</div>
            <div class="card-body">
                @foreach (var t in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                               value="@t" checked="@(theme == t)"
                               @onchange="() => theme = t" />
                        <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header">Font Size</div>
            <div class="card-body">
                @foreach (var s in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check form-check-inline">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
                               value="@s" checked="@(fontSize == s)"
                               @onchange="() => fontSize = s" />
                        <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header">Language</div>
            <div class="card-body">
                <select class="form-select" @bind="language">
                    @foreach (var lang in languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-body">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                    <label class="form-check-label" for="compactMode">
                        <strong>Compact Mode</strong>
                        <div class="text-muted small">Reduce spacing and padding throughout the UI</div>
                    </label>
                </div>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
            @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save
        </button>
    </div>

    <div class="col-md-6">
        <AppearancePreview Settings="@CurrentSettings" />
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Appearance { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private string? statusMessage;
    private bool isSaving;
