@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
@namespace sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Components.Pages.Settings

<h4 class="mb-4">Security Settings</h4>

<ChangePasswordPanel OnChangePassword="HandleChangePassword" />

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small">Add an extra layer of security to your account</div>
            </div>
            <div class="d-flex align-items-center gap-2">
                @if (twoFactorEnabled)
                {
                    <span class="badge bg-success">Enabled</span>
                }
                else
                {
                    <span class="badge bg-warning text-dark">Disabled</span>
                }
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" @bind="twoFactorEnabled" />
                </div>
            </div>
        </div>
    </div>
</div>

@if (Security?.LastPasswordChange is not null)
{
    <div class="text-muted small mb-3">
        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
    </div>
}

<ActiveSessionsTable Sessions="sessions" OnRevoke="HandleRevoke" />

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool twoFactorEnabled;
    private List<ActiveSession> sessions = new();
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (Security is not null && !initialized)
        {
            twoFactorEnabled = Security.TwoFactorEnabled;
            sessions = Security.Sessions.ToList();
            initialized = true;
        }
    }

    private async Task HandleChangePassword((string Current, string New) passwords) =>
        await OnChangePassword.InvokeAsync(passwords);

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
        sessions = sessions.Where(s => s.Id != sessionId).ToList();
    }
}

@using sv_91c7df16c97b4f2ca5a04ec9e0ecf4d2.Models
